mapper.select:
select m.*, p.status AS participantStatus,
CASE WHEN f.favorite_id IS 
NULL THEN 0 ELSE 1 END AS favorite
from team_match_participant p
join team_match m 
on m.team_match_id = p.team_match_id
LEFT JOIN favorite f
on f.match_id = m.team_match_id
AND f.user_id = #{userId}
AND f.match_type = 'Team'
WHERE p.user_id = #{userId}
AND p.status IN ('결제완료')

	AND m.sport = #{sport}


	AND m.status = #{status}

 AND m.match_date >= #{startDate} 
 AND m.match_date <= #{endDate} 
ORDER BY m.match_date, m.team_match_id
LIMIT #{size} OFFSET
#{offset}

SELECT COUNT(*) FROM team_match_participant p JOIN team_match m ON m.team_match_id = p.team_match_id WHERE p.user_id = #{userId} AND p.status IN ('결제완료')
AND m.match_date >= STR_TO_DATE(CONCAT(#{month}, '-01'), '%Y-%m-%d') AND m.match_date < DATE_ADD(STR_TO_DATE(CONCAT(#{month}, '-01'), '%Y-%m-%d'), INTERVAL 1 MONTH)
AND m.sport = #{sport}
AND m.status = #{status}

SELECT DISTINCT DATE_FORMAT(m.match_date, '%Y-%m-%d')
FROM team_match_participant p
JOIN team_match m
ON m.team_match_id = p.team_match_id
WHERE p.user_id = #{userId}
AND p.status IN ('결제완료')

	AND m.sport = #{sport}


	AND m.status = #{status}

select tm.*,
exists ( select 1 from favorite f where f.user_id = #{userId} and f.match_id = tm.team_match_id and f.match_type = 'Team' ) as favorite
false as favorite
from team_match tm where coalesce(deleted, 0) = 0 AND status = '모집중'
AND sport IN #{s}
AND region IN #{r}
AND (gender = #{gender} OR gender = '성별 무관')
AND DAYOFWEEK(match_date) IN
1 2 3 4 5 6 7 0
AND (
skill_intro = true skill_beginner = true skill_intermediate = true skill_advanced = true 1 = 0
)
AND ( age_60_plus = true
OR age_20s = true OR age_30s = true OR age_40s = true OR age_50s = true
)
AND match_people IN #{p}
AND match_date >= #{startDate}
AND match_date <= #{endDate}
AND (title LIKE CONCAT('%', #{keyword}, '%') OR content LIKE CONCAT('%', #{keyword}, '%'))
order by created_at desc, team_match_id desc limit #{offset}, 5

select count(*) from team_match where coalesce(deleted, 0) = 0 AND status = '모집중'
AND sport IN #{s}
AND region IN #{r}
AND (gender = #{gender} OR gender = '성별 무관')
AND DAYOFWEEK(match_date) IN
1 2 3 4 5 6 7 0
AND (
skill_intro = true skill_beginner = true skill_intermediate = true skill_advanced = true 1 = 0
)
AND ( age_60_plus = true
OR age_20s = true OR age_30s = true OR age_40s = true OR age_50s = true
)
AND match_people IN #{p}
AND match_date >= #{startDate}
AND match_date <= #{endDate}
AND (title LIKE CONCAT('%', #{keyword}, '%') OR content LIKE CONCAT('%', #{keyword}, '%'))
